import re


_MILLISECONDS = {"w": 604800000, "d": 86400000, "h": 3600000,
                 "m": 60000, "s": 1000, "ms": 1}
_COMPONENT = re.compile(r"([0-9]+)(?:\.([0-9]+))?(ms|[wdhms])")


def _integer(digits):
    # Parse in chunks to support values beyond Python's decimal conversion limit.
    value = 0
    for start in range(0, len(digits), 9):
        chunk = digits[start:start + 9]
        value = value * 10 ** len(chunk) + int(chunk)
    return value


def parse_duration(text):
    """Return the duration in milliseconds, rounding ties away from zero."""
    if not isinstance(text, str):
        raise TypeError("expected a duration string")
    text = text.strip()
    negative = text.startswith("-")
    pos = int(negative)
    previous = None
    total = 0
    while True:
        match = _COMPONENT.match(text, pos)
        if match is None:
            raise ValueError("expected a duration component")
        whole, fraction, unit = match.groups()
        scale = _MILLISECONDS[unit]
        if previous is not None and scale >= previous:
            raise ValueError("units must be in descending order")
        previous = scale
        total += _integer(whole) * scale
        pos = match.end()
        if fraction is not None:
            if pos != len(text):
                raise ValueError("only the final component may have a fraction")
            denominator = 10 ** len(fraction)
            total += (2 * _integer(fraction) * scale + denominator) // (2 * denominator)
        if pos == len(text):
            return -total if negative else total
        if text[pos] == " ":
            pos += 1
